write(A/'switch16.svg',svg('<ellipse cx="500" cy="650" rx="365" ry="28" fill="#DDE3E9"/><path d="M130 470l130-95h610L840 470z" fill="#536174"/><path d="M130 470h710v135H130z" fill="#303D4D"/><path d="M840 470l30-95v130l-30 100z" fill="#17212B"/>'+ports+'<rect x="800" y="540" width="15" height="35" fill="#101B2B" stroke="#A9B2BC" stroke-width="2"/><rect x="821" y="540" width="15" height="35" fill="#101B2B" stroke="#A9B2BC" stroke-width="2"/>'))
write(A/'charger.svg',svg('<ellipse cx="500" cy="715" rx="260" ry="34" fill="#DDE3E9"/><path d="M280 560l95-175h275l90 175v120H280z" fill="#273342" stroke="#596574" stroke-width="5"/><path d="M325 545l70-125h240l63 125z" fill="#101B2B"/><rect x="400" y="437" width="225" height="65" rx="14" fill="#354254"/><path d="M465 468h80" stroke="#C7A862" stroke-width="9"/><rect x="470" y="605" width="60" height="9" rx="4" fill="#2358D5"/>'))
