# Copy deck in page order: useful without reading source HTML.
from html.parser import HTMLParser
class Extract(HTMLParser):
    def __init__(self):super().__init__();self.lines=[]
    def handle_data(self,data):
        if data.strip():self.lines.append(data.strip())
copy=['# Готовые тексты LegacyLab\n\nПорядок блоков соответствует прототипу.\n']
for path,(title,desc,body) in PAGES.items():
    if path.startswith('/equipment/') and path!='/equipment/r-450/':continue
    e=Extract();e.feed(body);copy.extend([f'\n## {path}\n\nTitle: {title}\n\nDescription: {desc}\n','\n\n'.join(e.lines)])
copy+=['\n## Общая навигация, подвал и модальная форма\n'];e=Extract();e.feed(HEADER+FOOTER+MODAL);copy+=['\n\n'.join(e.lines)]
write(R/'docs/02-copy-deck.md','\n'.join(copy))
print(f'Built {len(PAGES)} pages; 12 synchronized product records; CSV and copy deck')
